def validate_versions(versions: dict[str, str]) -> None:
    from fastapi import HTTPException

    if versions != REQUIRED_DOCUMENTS:
        raise HTTPException(
            409,
            detail={
                "error": "legal_versions_changed",
                "detail": "Прочитайте и подтвердите актуальные документы.",
            },
        )
